package com.badrulamin.University_Management.entity;  import com.fasterxml.jackson.annotation.JsonProperty; import jakarta.persistence.*; import jakarta.validation.constraints.NotNull; import lombok.AllArgsConstructor; import lombok.Getter; import lombok.NoArgsConstructor; import lombok.Setter;  import java.math.BigDecimal;  @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Entity @Table(name = "admission_results") public class AdmissionResult extends BaseEntity {      @NotNull     @ManyToOne(fetch = FetchType.LAZY)     @JoinColumn(name = "admission_candidate_id", nullable = false)     private AdmissionCandidate admissionCandidate;      @NotNull     @ManyToOne(fetch = FetchType.LAZY)     @JoinColumn(name = "admission_test_id", nullable = false)     private AdmissionTest admissionTest;      @NotNull     @Column(name = "marks_obtained", nullable = false, precision = 6, scale = 2)     private BigDecimal marksObtained;      @Column(name = "`rank`")     private Integer rank;      @Column(length = 50)     private String status;      @Column(columnDefinition = "TEXT")     private String remarks;      @JsonProperty("admissionCandidateId")     public void setAdmissionCandidateId(Long id) {         if (id != null) {             this.admissionCandidate = new AdmissionCandidate();             this.admissionCandidate.setId(id);         }     }      @JsonProperty     public Long getAdmissionCandidateId() {         return this.admissionCandidate != null ? this.admissionCandidate.getId() : null;     }      @JsonProperty("admissionTestId")     public void setAdmissionTestId(Long id) {         if (id != null) {             this.admissionTest = new AdmissionTest();             this.admissionTest.setId(id);         }     }      @JsonProperty     public Long getAdmissionTestId() {         return this.admissionTest != null ? this.admissionTest.getId() : null;     } }